// เวลาประเทศไทย — Home Screen Widget (Scriptable)
// ตัวเลข 1-12 ใหญ่ขึ้น + ตัวเลขเวลาจัดกึ่งกลางจริง (ใช้ centerAlignText แทนการเล่น spacer เอง)

const FRAMES_B64 = [
"",
"",
"",
"",
"",
"",
"",
"",
"",
"",
"",
""
];

function getFrameImage(index) {
  const data = Data.fromBase64String(FRAMES_B64[index]);
  return Image.fromData(data);
}

function polar(cx, cy, radius, deg) {
  const ang = (deg - 90) * Math.PI / 180;
  return new Point(cx + radius * Math.cos(ang), cy + radius * Math.sin(ang));
}

function drawLine(ctx, p1, p2, color, width) {
  const path = new Path();
  path.move(p1);
  path.addLine(p2);
  ctx.addPath(path);
  ctx.setStrokeColor(color);
  ctx.setLineWidth(width);
  ctx.strokePath();
}

async function buildClockImage(handImage) {
  const S = 640;
  const ctx = new DrawContext();
  ctx.size = new Size(S, S);
  ctx.opaque = false;
  ctx.respectScreenScale = true;

  const cx = S / 2, cy = S / 2;
  const r = S / 2;

  ctx.setFillColor(new Color("#12162a"));
  ctx.fillEllipse(new Rect(cx - r, cy - r, r * 2, r * 2));

  for (let i = 0; i < 60; i++) {
    if (i % 5 === 0) continue;
    const deg = i * 6;
    drawLine(ctx, polar(cx, cy, r - 14, deg), polar(cx, cy, r - 6, deg), new Color("#ffffff", 0.22), 2);
  }
  // ตัวเลข 1-12 ใหญ่ขึ้น (40pt) และขยับเข้าขอบอีกนิดให้สมดุลกับขนาดใหม่
  for (let i = 0; i < 12; i++) {
    const deg = i * 30;
    drawLine(ctx, polar(cx, cy, r - 30, deg), polar(cx, cy, r - 6, deg), new Color("#ffd166"), 4);
    const np = polar(cx, cy, r - 62, deg);
    const label = i === 0 ? "12" : String(i);
    ctx.setFont(Font.boldSystemFont(58));
    ctx.setTextColor(new Color("#f4f6ff"));
    ctx.setTextAlignedCenter();
    ctx.drawTextInRect(label, new Rect(np.x - 42, np.y - 32, 84, 64));
  }

  if (handImage) {
    const handSize = r * 1.65;
    ctx.drawImageInRect(handImage, new Rect(cx - handSize / 2, cy - handSize / 2, handSize, handSize));
  }

  ctx.setFillColor(new Color("#ffd166"));
  ctx.fillEllipse(new Rect(cx - 7, cy - 7, 14, 14));

  return ctx.getImage();
}

function errorWidget(message) {
  const widget = new ListWidget();
  widget.backgroundColor = new Color("#0b0f1c");
  const t = widget.addText("Error: " + message);
  t.textColor = new Color("#ff8080");
  t.font = Font.systemFont(12);
  widget.refreshAfterDate = new Date(Date.now() + 5 * 60000);
  return widget;
}

async function createWidget() {
  const now = new Date();
  const h = now.getHours(), m = now.getMinutes();

  const frameIndex = Math.round(h + m / 60) % 12;
  const handImage = getFrameImage(frameIndex);

  const clockImage = await buildClockImage(handImage);

  const widget = new ListWidget();
  widget.backgroundImage = clockImage;
  widget.setPadding(0, 0, 0, 0);

  const family = (typeof config !== "undefined" && config.widgetFamily) ? config.widgetFamily : "large";
  const topGap = family === "large" ? 190 : 88;

  widget.addSpacer(topGap);

  // ตัวเลขเวลาเดินสด จัดกึ่งกลางแนวนอนจริง ๆ ด้วย centerAlignText()
  const midnight = new Date(now);
  midnight.setHours(0, 0, 0, 0);

  const dateEl = widget.addDate(midnight);
  dateEl.applyTimerStyle();
  dateEl.textColor = new Color("#ffd166");
  dateEl.font = Font.semiboldSystemFont(family === "large" ? 22 : 15);
  dateEl.centerAlignText();

  widget.addSpacer();

  widget.refreshAfterDate = new Date(Date.now() + 60000);

  return widget;
}

let widget;
try {
  widget = await createWidget();
} catch (e) {
  widget = errorWidget(String(e));
}

if (config.runsInWidget) {
  Script.setWidget(widget);
} else {
  await widget.presentLarge();
}
Script.complete();
